use crate::aap::caps::state_read;

/// The one key this node reads from its `'subscriptions'` store. The value is
/// one feed URL per line.
const SUBSCRIPTIONS_KEY: &str = "urls";

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let raw = match state_read::get(SUBSCRIPTIONS_KEY) {
            Some(raw) => raw,
            // `ensures present(urls)` must hold of every output. With no
            // stored subscriptions there is no valid output to produce, so
            // trap rather than return an empty list that could violate it.
            None => panic!("LoadSubscriptions: no subscriptions stored under '{}'", SUBSCRIPTIONS_KEY),
        };

        let urls: Vec<String> = raw
            .lines()
            .map(|line| line.trim())
            .filter(|line| !line.is_empty())
            .map(|line| line.to_string())
            .collect();

        if urls.is_empty() {
            // Same reasoning as above: an empty subscription list would not
            // satisfy `present(urls)` under the non-empty reading.
            panic!("LoadSubscriptions: stored subscription list is empty");
        }

        SubscriptionList { urls }
    }
}

export!(Node);
